from z3 import *

n_cliques = 5
clique_size = 4
n_vertices = n_cliques * clique_size
m = 46

X = [[Int(f'x_{g}_{i}') for i in range(clique_size)] for g in range(n_cliques)]

s = Solver()

for g in range(n_cliques):
    for i in range(clique_size):
        s.add(X[g][i] >= 0, X[g][i] <= m)

all_vars = [X[g][i] for g in range(n_cliques) for i in range(clique_size)]
s.add(Distinct(all_vars))

edges = []
for g in range(n_cliques):
    for i in range(clique_size):
        for j in range(i+1, clique_size):
            edges.append((X[g][i], X[g][j]))
for g in range(n_cliques-1):
    for i in range(clique_size):
        edges.append((X[g][i], X[g+1][i]))

assert len(edges) == m

diffs = [Abs(u - v) for u, v in edges]
s.add(Distinct(diffs))

s.add(X[0][0] == 0)
s.add(X[0][0] < X[0][1], X[0][1] < X[0][2], X[0][2] < X[0][3])
s.add(Sum([X[0][i] for i in range(clique_size)]) <= Sum([X[4][i] for i in range(clique_size)]))

print("Starting solver...")
result = s.check()
print(result)
if result == sat:
    model = s.model()
    labels = [[model.evaluate(X[g][i]).as_long() for i in range(clique_size)] for g in range(n_cliques)]
    print(labels)
    used = set()
    diffs_set = set()
    ok = True
    for g in range(n_cliques):
        for i in range(clique_size):
            if labels[g][i] in used:
                ok = False
            used.add(labels[g][i])
    for g in range(n_cliques):
        for i in range(clique_size):
            for j in range(i+1, clique_size):
                d = abs(labels[g][i] - labels[g][j])
                if d in diffs_set:
                    ok = False
                diffs_set.add(d)
    for g in range(n_cliques-1):
        for i in range(clique_size):
            d = abs(labels[g][i] - labels[g+1][i])
            if d in diffs_set:
                ok = False
            diffs_set.add(d)
    print("Verification:", ok, "diffs count:", len(diffs_set), "expected:", m)
    flat = [labels[g][i] for g in range(n_cliques) for i in range(clique_size)]
    print("Labels flat:", flat)
else:
    print("No solution found by Z3")

